import{_ as t,o as s,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const m=JSON.parse('{"title":"Tenant API v1 — Estimates","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — Estimates | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-estimates"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — Estimates | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-estimates"}]]},"headers":[],"relativePath":"api/tenant-v1-estimates.md","filePath":"api/tenant-v1-estimates.md","lastUpdated":1788644779000}'),i={name:"api/tenant-v1-estimates.md"};function d(c,e,n,r,l,p){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-estimates" tabindex="-1">Tenant API v1 — Estimates <a class="header-anchor" href="#tenant-api-v1-—-estimates" aria-label="Permalink to &quot;Tenant API v1 — Estimates&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:estimates</code>, plus permission middleware / policies.</p><p>Requires the <strong>Invoices</strong> module (hard <code>module_dependencies</code> row) — Marketplace blocks installing Estimates on a workspace that doesn&#39;t already have Invoices, since converting an estimate always creates a <code>CustomerInvoice</code>.</p><p>Assignee scoping: without <code>estimates.assign</code> (and not superadmin), list/stats/view/update/<strong>send</strong>/<strong>accept</strong>/<strong>convert</strong> only include estimates where <code>assigned_to</code> is the current user.</p><h2 id="stats" tabindex="-1">Stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;Stats&quot;">​</a></h2><h3 id="get-estimates-stats" tabindex="-1">GET <code>/estimates/stats</code> <a class="header-anchor" href="#get-estimates-stats" aria-label="Permalink to &quot;GET `/estimates/stats`&quot;">​</a></h3><p>Same filters as list (minus pagination/sort). Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;total_estimates&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;my_estimates&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;draft&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;accepted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rejected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expired&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;accepted_value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;converted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;scope&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org | mine&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>accepted_value</code> sums <code>total</code> across estimates with <code>status = accepted</code>. <code>converted</code> counts estimates that already have a linked <code>CustomerInvoice</code>.</p><h2 id="estimates-crud" tabindex="-1">Estimates CRUD <a class="header-anchor" href="#estimates-crud" aria-label="Permalink to &quot;Estimates CRUD&quot;">​</a></h2><h3 id="get-estimates" tabindex="-1">GET <code>/estimates</code> <a class="header-anchor" href="#get-estimates" aria-label="Permalink to &quot;GET `/estimates`&quot;">​</a></h3><p>Query: <code>search</code> (matches <code>title</code> or <code>number</code>), <code>status</code> (<code>draft</code>|<code>sent</code>|<code>accepted</code>|<code>rejected</code>|<code>expired</code>), <code>contact_id</code>, <code>company_id</code>, <code>quotation_id</code>, <code>opportunity_id</code>, <code>assigned_to</code> (<code>unassigned</code> or user id), <code>my_estimates</code>, <code>trashed</code> (<code>true</code>|<code>only</code>), <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>List items include <code>status</code>, <code>currency</code>, <code>subtotal</code>/<code>discount_total</code>/<code>tax_total</code>/<code>total</code>, <code>issue_date</code>, <code>valid_until</code>, <code>contact</code>/<code>company</code>/<code>opportunity</code>/<code>quotation</code> refs, <code>converted_invoice</code> ref (<code>number</code>/<code>status</code>) when present, assignee/creator refs, and <code>latest_note</code>.</p><h3 id="post-estimates" tabindex="-1">POST <code>/estimates</code> <a class="header-anchor" href="#post-estimates" aria-label="Permalink to &quot;POST `/estimates`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>notes</code> (HTML memo, sanitized server-side), <code>terms_and_conditions</code> (HTML, sanitized server-side), <code>currency</code> (3-letter, default <code>USD</code>), <code>valid_until</code> (date), <code>contact_id</code>, <code>company_id</code> (optional, module-entitlement + assignee-scope validated via <code>LinkableContact</code>/<code>LinkableCompany</code>), <code>quotation_id</code>, <code>opportunity_id</code> (optional, tenant-scoped existence checks), <code>assigned_to</code>, <code>line_discount_type</code> (<code>none</code>|<code>percent</code>|<code>fixed</code>), <code>lines</code> (array of <code>{ product_id?, name, body?, quantity, unit_price, tax_rate, sort_order, discount_value }</code>). <code>product_id</code> is optional and requires the Products module, <code>products.view</code> (or superadmin), and an active non-trashed product (<code>LinkableProduct</code>). <code>body</code> is optional HTML line details. <code>discount_value</code> is required on a line when <code>line_discount_type</code> is not <code>none</code>. The server stores client-sent <code>name</code>/<code>body</code>/<code>unit_price</code> as-is (does not re-copy from the product catalog).</p><p><code>subtotal</code>, <code>discount_total</code>, <code>tax_total</code>, and <code>total</code> are computed server-side from <code>lines</code> and document discount — do not send them. Tax is calculated after discounts. Status always starts at <code>draft</code>; <code>number</code> is auto-generated (<code>EST-00001</code>, configurable via the <code>estimates_number_prefix</code> tenant setting).</p><h3 id="get-estimates-id" tabindex="-1">GET <code>/estimates/{id}</code> <a class="header-anchor" href="#get-estimates-id" aria-label="Permalink to &quot;GET `/estimates/{id}`&quot;">​</a></h3><p>Includes contact, company, opportunity, quotation, converted invoice, assignee, creator, lines (<code>product_id</code>, optional <code>product</code> <code>{id,sku,name}</code> when loaded, <code>name</code>, <code>body</code>, <code>discount_value</code>), document <code>line_discount_type</code> / <code>discount_total</code>, <code>notes</code>, <code>terms_and_conditions</code>, and timeline activities. Embedded <code>notes</code> and timeline/domain <code>activities</code> are <strong>newest-first</strong> (<code>created_at</code> DESC, then <code>id</code> DESC).</p><h3 id="get-estimates-id-pdf" tabindex="-1">GET <code>/estimates/{id}/pdf</code> <a class="header-anchor" href="#get-estimates-id-pdf" aria-label="Permalink to &quot;GET `/estimates/{id}/pdf`&quot;">​</a></h3><p>Permission: <code>estimates.view</code> (assignee-scoped). Extra limiter <code>throttle:estimates-pdf</code>. Returns <code>application/pdf</code> attachment. Branded layout matches invoices (logo, button color, company profile). Includes sanitized memo HTML, line items, and discount/tax/total breakdown.</p><h3 id="put-estimates-id" tabindex="-1">PUT <code>/estimates/{id}</code> <a class="header-anchor" href="#put-estimates-id" aria-label="Permalink to &quot;PUT `/estimates/{id}`&quot;">​</a></h3><p>Partial update of <strong>draft</strong> estimates only — including replacing the full <code>lines</code> set (recalculates totals from <code>line_discount_type</code> and per-line <code>discount_value</code>). Non-draft estimates return 422 on <code>status</code> (<code>Only draft estimates can be edited.</code>). Assignment after send uses <code>POST /estimates/{id}/assign</code>.</p><h3 id="delete-estimates-id" tabindex="-1">DELETE <code>/estimates/{id}</code> <a class="header-anchor" href="#delete-estimates-id" aria-label="Permalink to &quot;DELETE `/estimates/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>estimates.delete</code>.</p><h3 id="post-estimates-id-restore" tabindex="-1">POST <code>/estimates/{id}/restore</code> <a class="header-anchor" href="#post-estimates-id-restore" aria-label="Permalink to &quot;POST `/estimates/{id}/restore`&quot;">​</a></h3><p>Permission: <code>estimates.restore</code>.</p><h3 id="delete-estimates-id-force" tabindex="-1">DELETE <code>/estimates/{id}/force</code> <a class="header-anchor" href="#delete-estimates-id-force" aria-label="Permalink to &quot;DELETE `/estimates/{id}/force`&quot;">​</a></h3><p>Permanently delete a soft-deleted estimate. Permission: <code>estimates.force.delete</code> (owner/superadmin only by default).</p><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="post-estimates-id-assign" tabindex="-1">POST <code>/estimates/{id}/assign</code> <a class="header-anchor" href="#post-estimates-id-assign" aria-label="Permalink to &quot;POST `/estimates/{id}/assign`&quot;">​</a></h3><p><code>{ &quot;assigned_to&quot;: number|null }</code></p><p>Permission: <code>estimates.assign</code>.</p><h3 id="post-estimates-id-send" tabindex="-1">POST <code>/estimates/{id}/send</code> <a class="header-anchor" href="#post-estimates-id-send" aria-label="Permalink to &quot;POST `/estimates/{id}/send`&quot;">​</a></h3><p>Transitions <code>draft → sent</code>. Backfills <code>issue_date</code> to today if unset. Permission: <code>estimates.send</code> (assignee-scoped unless the actor has <code>estimates.assign</code> or is superadmin). <strong>Status-only</strong> — does not email or generate a PDF.</p><h3 id="post-estimates-id-email" tabindex="-1">POST <code>/estimates/{id}/email</code> <a class="header-anchor" href="#post-estimates-id-email" aria-label="Permalink to &quot;POST `/estimates/{id}/email`&quot;">​</a></h3><p><code>{ &quot;to&quot;?: string[], &quot;cc&quot;?: string[], &quot;bcc&quot;?: string[], &quot;subject&quot;: string, &quot;message&quot;: string, &quot;attach_pdf&quot;?: boolean }</code></p><p>Permission: <code>estimates.send</code> (assignee-scoped unless the actor has <code>estimates.assign</code> or is superadmin). Throttle: <code>billing-document-email</code> (10/min per user).</p><p>Requires the estimate to already be sent — allowed statuses: <code>sent</code>, <code>accepted</code>, <code>rejected</code>, <code>expired</code>. Draft returns 422 on <code>status</code>.</p><p>When <code>to</code> is omitted, resolves the recipient from the linked contact email, then company email. If no address is found, returns 422 on <code>to</code>.</p><p>Queues a branded email via the tenant mailer (optional PDF attachment from <code>EstimatePdfService</code>). Records an <code>emailed</code> timeline entry and a tenant email log row (<code>notification_type</code>: <code>estimate.emailed</code>).</p><h3 id="post-estimates-id-accept" tabindex="-1">POST <code>/estimates/{id}/accept</code> <a class="header-anchor" href="#post-estimates-id-accept" aria-label="Permalink to &quot;POST `/estimates/{id}/accept`&quot;">​</a></h3><p>Transitions <code>sent → accepted</code>. Permission: <code>estimates.accept</code> (assignee-scoped unless the actor has <code>estimates.assign</code> or is superadmin).</p><h3 id="post-estimates-id-status" tabindex="-1">POST <code>/estimates/{id}/status</code> <a class="header-anchor" href="#post-estimates-id-status" aria-label="Permalink to &quot;POST `/estimates/{id}/status`&quot;">​</a></h3><p><code>{ &quot;status&quot;: &quot;draft&quot;|&quot;sent&quot;|&quot;accepted&quot;|&quot;rejected&quot;|&quot;expired&quot; }</code></p><p>Authorization depends on the target status:</p><ul><li><code>sent</code> → <code>estimates.send</code></li><li><code>accepted</code> → <code>estimates.accept</code></li><li>other allowed transitions (e.g. <code>rejected</code>, <code>expired</code>) → <code>estimates.update</code></li></ul><p>Rejects disallowed transitions (including re-sending an already-<code>sent</code> estimate) with a 422 validation error on <code>status</code>. Records a <code>status_changed</code> timeline entry.</p><h3 id="post-estimates-id-convert" tabindex="-1">POST <code>/estimates/{id}/convert</code> <a class="header-anchor" href="#post-estimates-id-convert" aria-label="Permalink to &quot;POST `/estimates/{id}/convert`&quot;">​</a></h3><p>Converts a <strong>sent</strong> or <strong>accepted</strong> estimate into a <strong>draft</strong> <code>CustomerInvoice</code>:</p><ul><li>Requires the <strong>Invoices</strong> module to be entitled (soft, call-time check in addition to the hard Marketplace dependency). Returns 422 if Invoices is not installed.</li><li>Creates the invoice with the estimate&#39;s <code>title</code>, <code>notes</code>, <code>terms_and_conditions</code>, <code>currency</code>, <code>line_discount_type</code>, <code>contact_id</code>, <code>company_id</code>, <code>quotation_id</code>, <code>assigned_to</code>, and a copy of every line item (<code>name</code>, <code>body</code>, <code>discount_value</code>, quantities/prices/tax)</li><li>Sets <code>customer_invoices.estimate_id</code> on create (unique nullable column — one-shot at the database)</li><li>Transitions the estimate to <code>accepted</code> if it wasn&#39;t already</li><li>Records a <code>converted</code> activity on the estimate</li><li>Serializes with <code>lockForUpdate</code> on the estimate (and linked quotation when present)</li></ul><p>Permission: <code>estimates.convert</code> (assignee-scoped unless the actor has <code>estimates.assign</code> or is superadmin). Rejects with a 422 on <code>status</code> if the estimate is <code>draft</code>/<code>rejected</code>/<code>expired</code>, if it has already been converted (including soft-deleted invoices — restore or force-delete to recover), or if the estimate’s linked quotation already has any invoice (<code>QuotationInvoiceGuard</code>). Returns the created <strong>invoice</strong> (<code>CustomerInvoiceResource</code>), not an estimate, with HTTP 201.</p><h3 id="post-estimates-id-notes" tabindex="-1">POST <code>/estimates/{id}/notes</code> <a class="header-anchor" href="#post-estimates-id-notes" aria-label="Permalink to &quot;POST `/estimates/{id}/notes`&quot;">​</a></h3><p><code>{ &quot;body&quot;: string }</code></p><p>Permission: <code>estimates.update</code>.</p><h3 id="get-estimates-id-timeline" tabindex="-1">GET <code>/estimates/{id}/timeline</code> <a class="header-anchor" href="#get-estimates-id-timeline" aria-label="Permalink to &quot;GET `/estimates/{id}/timeline`&quot;">​</a></h3><p>Domain timeline entries (<code>created</code>, <code>updated</code>, <code>assigned</code>, <code>status_changed</code>, <code>converted</code>, <code>note_added</code>, <code>deleted</code>, <code>restored</code>, <code>emailed</code>).</p>',57)])])}const u=t(i,[["render",d]]);export{m as __pageData,u as default};
